1	/**
2	 * Repository anchor. The repository is found from `git rev-parse --git-common-dir`, never `--show-toplevel`, so a
3	 * command run inside a linked worktree resolves the same main checkout, registry and sibling list as one run in the
4	 * main checkout. Hooks (WP-1313) and per-branch variables (WP-1314) attach to `Repo.commonDir`.
5	 */
6	import * as fs from "node:fs";
7	import * as path from "node:path";
8	import { rememberRepository } from "../core/checkout_trust.js";
9	import { git, gitOut, GitError, UntrustedCheckoutError } from "./git.js";
10	
11	/** `startDir` is not inside a Git repository (as opposed to Git refusing it, or failing). */
12	export class NotARepositoryError extends Error {
13	  constructor() { super("not inside a git repository"); this.name = "NotARepositoryError"; }
14	}
15	
16	export interface WorktreeEntry {
17	  path: string;
18	  head: string;
19	  branch: string | null;
20	  detached: boolean;
21	  bare: boolean;
22	  locked: boolean;
23	  prunable: boolean;
24	  isMain: boolean;
25	}
26	
27	export interface Repo {
28	  /** Directory commands were started from (real path). */
29	  cwd: string;
30	  /** `git rev-parse --git-common-dir`, absolute and resolved. */
31	  commonDir: string;
32	  /** The main checkout. */
33	  repoPath: string;
34	  repoName: string;
35	  entries: WorktreeEntry[];
36	}
37	
38	export function parseWorktreeList(raw: string): WorktreeEntry[] {
39	  const entries: WorktreeEntry[] = [];
40	  let current: Partial<WorktreeEntry> | undefined;
41	  const flush = () => {
42	    if (current?.path) {
43	      entries.push({
44	        path: current.path, head: current.head ?? "", branch: current.branch ?? null, detached: current.detached ?? false,
45	        bare: current.bare ?? false, locked: current.locked ?? false, prunable: current.prunable ?? false, isMain: entries.length === 0,
46	      });
47	    }
48	    current = undefined;
49	  };
50	  for (const token of raw.split("\0")) {
51	    if (token === "") { flush(); continue; }
52	    current ??= {};
53	    if (token.startsWith("worktree ")) current.path = token.slice(9);
54	    else if (token.startsWith("HEAD ")) current.head = token.slice(5);
55	    else if (token.startsWith("branch ")) current.branch = token.slice(7).replace(/^refs\/heads\//, "");
56	    else if (token === "detached") current.detached = true;
57	    else if (token === "bare") current.bare = true;
58	    else if (token === "locked" || token.startsWith("locked ")) current.locked = true;
59	    else if (token === "prunable" || token.startsWith("prunable ")) current.prunable = true;
60	  }
61	  flush();
62	  return entries;
63	}
64	
65	export function listEntries(cwd: string): WorktreeEntry[] {
66	  return parseWorktreeList(git(cwd, ["worktree", "list", "--porcelain", "-z"]).stdout);
67	}
68	
69	export function openRepo(startDir: string): Repo {
70	  let cwd: string;
71	  try {
72	    cwd = fs.realpathSync(startDir);
73	  } catch {
74	    throw new Error("the working directory does not exist");
75	  }
76	  let commonDir: string;
77	  try {
78	    commonDir = fs.realpathSync(gitOut(cwd, ["rev-parse", "--path-format=absolute", "--git-common-dir"]));
79	  } catch (err) {
80	    if (err instanceof UntrustedCheckoutError) throw err;
81	    if (err instanceof GitError) throw new NotARepositoryError();
82	    throw err;
83	  }
84	  const entries = listEntries(cwd);
85	  const main = entries[0];
86	  if (!main || main.bare) throw new Error("bare repositories are not supported by `nexus worktree`");
87	  // `git worktree list` names the git directory itself as the main worktree when it is not `<checkout>/.git`
88	  // (`--separate-git-dir`), and nothing in the common directory leads back to the checkout, so the anchor would be wrong.
89	  if (path.basename(commonDir) !== ".git") throw new Error("repositories whose git directory is not <checkout>/.git (for example --separate-git-dir) are not supported by `nexus worktree`");
90	  const repoPath = fs.realpathSync(main.path);
91	  rememberRepository(commonDir, entries.filter((entry) => !entry.isMain).map((entry) => entry.path));
92	  return { cwd, commonDir, repoPath, repoName: path.basename(repoPath), entries };
93	}
94	
95	export function refExists(repo: Repo, fullRef: string): boolean {
96	  return git(repo.cwd, ["show-ref", "--verify", "--quiet", fullRef], { allowFailure: true }).status === 0;
97	}
98	
99	/** The repository's default branch: origin/HEAD if it names a local branch, else main/master/trunk/develop, else the main checkout's branch. */
100	export function defaultBranch(repo: Repo): string | undefined {
101	  const origin = git(repo.cwd, ["symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD"], { allowFailure: true });
102	  if (origin.status === 0) {
103	    const name = origin.stdout.trim().replace(/^origin\//, "");
104	    if (name && refExists(repo, `refs/heads/${name}`)) return name;
105	  }
106	  for (const name of ["main", "master", "trunk", "develop"]) if (refExists(repo, `refs/heads/${name}`)) return name;
107	  return repo.entries[0].branch ?? undefined;
108	}
109	
110	/**
111	 * The commit a local branch names, or undefined. Always `refs/heads/<name>`: a tag (or any other ref) that shares the
112	 * branch's short name would otherwise win Git's ambiguity rules and stand in for the branch.
113	 */
114	export function resolveBranchCommit(repo: Repo, name: string): string | undefined {
115	  return resolveCommit(repo, `refs/heads/${name}`);
116	}
117	
118	/** The commit a ref names, or undefined. The ref is passed after `--end-of-options`. */
119	export function resolveCommit(repo: Repo, ref: string): string | undefined {
120	  const out = git(repo.cwd, ["rev-parse", "--verify", "--quiet", "--end-of-options", `${ref}^{commit}`], { allowFailure: true });
121	  const sha = out.stdout.trim();
122	  return out.status === 0 && /^[0-9a-f]{40,64}$/.test(sha) ? sha : undefined;
123	}
124	
125	/** The entry whose directory contains the real working directory (deepest wins). */
126	export function currentEntry(repo: Repo): WorktreeEntry | undefined {
127	  let best: WorktreeEntry | undefined;
128	  let bestLength = -1;
129	  for (const entry of repo.entries) {
130	    let real: string;
131	    try { real = fs.realpathSync(entry.path); } catch { continue; }
132	    if ((repo.cwd === real || repo.cwd.startsWith(real + path.sep)) && real.length > bestLength) {
133	      best = entry;
134	      bestLength = real.length;
135	    }
136	  }
137	  return best;
138	}
